package io.cascadeshield.sim;

import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.annotation.PreDestroy;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import static io.cascadeshield.sim.BenchmarkModels.*;

/** Isolated worker and persistent results. This service has no live SimulationService dependency. */
@Service
public class BenchmarkService {
    public record Request(Map<String,Object> parameters,List<String> policies,String comparisonMode,List<String> ablations) {}
    private final RoadGraph graph;private final ObjectMapper mapper;private final BenchmarkRepository repository;private final String digest;
    private final BenchmarkScenarioGenerator generator;private final BenchmarkPolicyRunner runner;
    private final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,0,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->{Thread t=new Thread(r,"isolated-benchmark-worker");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
    public BenchmarkService(BenchmarkRepository repository,ObjectMapper mapper,@Value("${simulator.graph-path}")String graphPath)throws Exception{this.repository=repository;this.mapper=mapper;Path path=Path.of(graphPath);graph=RoadGraph.load(path,mapper);digest=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(Files.readAllBytes(path)));generator=new BenchmarkScenarioGenerator(graph,mapper);runner=new BenchmarkPolicyRunner(graph,mapper);repository.interrupted();}
    public Map<String,Object> catalog(){Map<String,Object> result=new LinkedHashMap<>();result.put("schemaVersion","cascadeshield.benchmark/1.0");result.put("networkId",graph.network.networkId());result.put("graphSha256",digest);result.put("provenance",PROVENANCE);result.put("presets",BenchmarkScenarioGenerator.presets());result.put("policies",BenchmarkPolicyRunner.catalog(false));result.put("equalActionPolicies",BenchmarkPolicyRunner.catalog(true));result.put("ablations",List.of(Map.of("id","FULL","name","Full enhancement"),Map.of("id","NO_TEMPORAL","name","Temporal dependencies disabled"),Map.of("id","NO_ADAPTIVE","name","Adaptive threshold disabled"),Map.of("id","NO_COUNTERFACTUAL","name","Counterfactual evaluation disabled")));result.put("parameterSchema",Map.of("truckCount",Map.of("min",2,"max",8),"seeds",Map.of("minItems",1,"maxItems",8),"horizonSec",Map.of("min",300,"max",7200)));result.put("unsupportedActions",List.of("Delivery reprioritization does not change the modeled queue.","Driver/vehicle reassignment lacks a validated spatial transfer model; no such action is offered."));result.put("selectionWeights",CounterfactualExperimentEngine.WEIGHTS);result.put("modeledCostRates",ExperimentMetrics.COST_RATES);result.put("liveStateIsolated",true);return result;}
    private static List<String> optionIds(List<String> supplied,List<String> fallback,String field){if(supplied==null)return fallback;for(String id:supplied)if(id==null||id.isBlank())throw ApiException.invalid(field+" must contain nonempty string IDs");return List.copyOf(supplied);}
    private List<Long> seeds(Request request){Object raw=request.parameters().getOrDefault("seeds",List.of(1L,2L,3L));if(!(raw instanceof List<?> values)||values.isEmpty()||values.size()>8)throw ApiException.invalid("Choose 1–8 deterministic seeds");List<Long> seeds=new ArrayList<>();for(Object value:values){if(!(value instanceof Number n)||!Double.isFinite(n.doubleValue())||n.longValue()!=n.doubleValue()||n.longValue()<0||n.longValue()>Integer.MAX_VALUE)throw ApiException.invalid("Seeds must be integers between 0 and 2147483647");if(seeds.contains(n.longValue()))throw ApiException.invalid("Seeds must be distinct");seeds.add(n.longValue());}return seeds;}
    private List<PolicySpec> selected(Request request){boolean equal="EQUAL_ACTIONS".equals(request.comparisonMode());if(!equal&&!"FULL".equals(request.comparisonMode()))throw ApiException.invalid("Comparison mode must be FULL or EQUAL_ACTIONS");Map<String,PolicySpec> catalog=new LinkedHashMap<>();for(PolicySpec p:BenchmarkPolicyRunner.catalog(equal))catalog.put(p.id(),p);List<String> ids=request.policies()==null||request.policies().isEmpty()?List.of("B0","B1","B2","B3","B4"):request.policies();if(new HashSet<>(ids).size()!=ids.size())throw ApiException.invalid("Policy IDs must be distinct");List<PolicySpec> result=new ArrayList<>();for(String id:ids){if(!catalog.containsKey(id))throw ApiException.invalid("Unsupported benchmark policy "+id);result.add(catalog.get(id));}List<String> ablations=request.ablations()==null?List.of("FULL"):request.ablations();if(new HashSet<>(ablations).size()!=ablations.size())throw ApiException.invalid("Ablations must be distinct");for(String name:ablations){if(!List.of("FULL","NO_TEMPORAL","NO_ADAPTIVE","NO_COUNTERFACTUAL").contains(name))throw ApiException.invalid("Unsupported ablation "+name);if(!"FULL".equals(name)){if(!ids.contains("B4"))throw ApiException.invalid("Ablations require B4");PolicySpec base=catalog.get("B4");result.add(new PolicySpec("B4_"+name,"B4: "+name,base.allowedActions(),!"NO_TEMPORAL".equals(name),!"NO_ADAPTIVE".equals(name),!"NO_COUNTERFACTUAL".equals(name)));}}return List.copyOf(result);}
    public synchronized Map<String,Object> submit(Request request){if(request==null||request.parameters()==null)throw ApiException.invalid("Scenario parameters are required");if(worker.getQueue().remainingCapacity()==0)throw new ApiException(429,"Benchmark worker queue is full; wait for a current comparison");Map<String,Object> parameters=mapper.convertValue(request.parameters(),Map.class);Object rawTrucks=parameters.getOrDefault("truckCount",4);if(!(rawTrucks instanceof Number tn)||!Double.isFinite(tn.doubleValue())||tn.doubleValue()!=tn.intValue())throw ApiException.invalid("truckCount must be a finite integer");int trucks=tn.intValue();if(trucks<2||trucks>8)throw ApiException.invalid("The interactive benchmark supports 2–8 trucks");Request frozen=new Request(parameters,optionIds(request.policies(),List.of("B0","B1","B2","B3","B4"),"policies"),request.comparisonMode()==null?"FULL":request.comparisonMode(),optionIds(request.ablations(),List.of("FULL"),"ablations"));List<Long> seeds=seeds(frozen);List<PolicySpec> policies=selected(frozen);String profile=String.valueOf(parameters.getOrDefault("profile","closure-contention"));Object rawHorizon=parameters.getOrDefault("horizonSec",2400);if(!(rawHorizon instanceof Number hn)||!Double.isFinite(hn.doubleValue())||hn.doubleValue()<300||hn.doubleValue()>7200)throw ApiException.invalid("Interactive horizonSec must be finite within 300 to 7200 seconds");generator.generate(profile,seeds.getFirst(),parameters);UUID id=UUID.randomUUID();repository.create(id,graph.network.networkId(),digest,frozen,seeds.size()*policies.size());try{worker.execute(()->execute(id,frozen,seeds,policies));}catch(RejectedExecutionException error){repository.failed(id,"Worker unavailable; rerun the saved request",null);throw new ApiException(503,"Benchmark worker unavailable");}return repository.get(id);}
    private void execute(UUID id,Request request,List<Long> seeds,List<PolicySpec> policies){List<ScenarioSpec> scenarios=new ArrayList<>();List<PolicyRun> runs=new ArrayList<>();try{repository.progress(id,0);String profile=String.valueOf(request.parameters().getOrDefault("profile","closure-contention"));for(long seed:seeds){ScenarioSpec scenario=generator.generate(profile,seed,request.parameters());scenarios.add(scenario);for(PolicySpec policy:policies){if(Thread.currentThread().isInterrupted())throw new InterruptedException("Worker stopped");PolicyRun run=runner.run(scenario,policy);if(!scenario.inputFingerprint().equals(run.inputFingerprint()))throw new IllegalStateException("A policy changed its paired initial inputs");runs.add(run);repository.progress(id,runs.size());}}Map<String,Object> summary=new LinkedHashMap<>();summary.put("comparisonMode",request.comparisonMode());summary.put("scenarioCount",scenarios.size());summary.put("runCount",runs.size());summary.put("identicalPairedInputs",true);summary.put("liveStateModified",false);summary.put("selectionWeights",CounterfactualExperimentEngine.WEIGHTS);summary.put("modeledCostRates",ExperimentMetrics.COST_RATES);summary.put("uncertainty","Run several seeds and use paired scenario/seed aggregation; reports are simulator outcomes, not observed field effectiveness.");repository.complete(id,new ComparisonResult("cascadeshield.benchmark/1.0",List.copyOf(scenarios),List.copyOf(runs),summary,PROVENANCE),runs.size());}catch(Exception error){repository.failed(id,error.getClass().getSimpleName()+": "+error.getMessage(),new ComparisonResult("cascadeshield.benchmark/1.0",List.copyOf(scenarios),List.copyOf(runs),Map.of("complete",false,"comparisonMode",request.comparisonMode()),PROVENANCE));}}
    public Map<String,Object> get(UUID id){return repository.get(id);}
    public List<Map<String,Object>> list(){return repository.list();}
    @SuppressWarnings("unchecked")
    public String export(UUID id,String format){Map<String,Object> job=get(id);if(!"COMPLETED".equals(job.get("status")))throw ApiException.conflict("Export requires a completed benchmark; missing outcomes are not fabricated");try{if("json".equals(format))return mapper.writerWithDefaultPrettyPrinter().writeValueAsString(job);if(!"csv".equals(format))throw ApiException.invalid("Export format must be json or csv");Map<String,Object> result=(Map<String,Object>)job.get("result");List<Map<String,Object>> runs=(List<Map<String,Object>>)result.get("runs");Map<String,Map<String,Object>> scenarios=new HashMap<>();for(Map<String,Object> s:(List<Map<String,Object>>)result.get("scenarios"))scenarios.put((String)s.get("id"),s);List<Map<String,Object>> rows=new ArrayList<>();for(Map<String,Object> run:runs){Map<String,Object> row=new LinkedHashMap<>();row.put("jobId",id);row.put("scenarioId",run.get("scenarioId"));row.put("profile",scenarios.get(run.get("scenarioId")).get("profile"));row.put("seed",run.get("seed"));row.put("policyId",run.get("policyId"));row.put("comparisonMode",((Map<?,?>)job.get("request")).get("comparisonMode"));row.put("inputFingerprint",run.get("inputFingerprint"));row.putAll((Map<String,Object>)run.get("metrics"));rows.add(row);}List<String> headers=new ArrayList<>(rows.getFirst().keySet());StringBuilder csv=new StringBuilder();csv.append(String.join(",",headers)).append('\n');for(Map<String,Object> row:rows){csv.append(headers.stream().map(h->cell(row.get(h))).collect(java.util.stream.Collectors.joining(","))).append('\n');}return csv.toString();}catch(ApiException e){throw e;}catch(Exception e){throw new IllegalStateException("Benchmark export failed",e);}}
    private static String cell(Object value){String s=value==null?"":String.valueOf(value);return "\""+s.replace("\"","\"\"")+"\"";}
    @PreDestroy public void stop(){worker.shutdownNow();}
}
